using System; using System.Linq; using System.Collections.Generic; using System.Web.Mvc; using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Controllers { public class OrdersController:Controller { private StoreContext db=new StoreContext(); [HttpPost,ValidateAntiForgeryToken] public ActionResult Checkout(string address){if(Session["Username"]==null)return RedirectToAction("Login","Account");var cart=Session["Cart"] as List<CartItem>;if(cart==null||cart.Count==0){TempData["Message"]="Giỏ hàng đang trống.";return RedirectToAction("Index","Cart");}var customer=db.Customers.FirstOrDefault(c=>c.Username==(string)Session["Username"]);if(customer==null)return RedirectToAction("Login","Account");var order=new StoreOrder{CustomerID=customer.CustomerID,OrderDate=DateTime.Today,TotalAmount=cart.Sum(x=>x.Total),PaymentStatus="Chờ xác nhận",AddressDelivery=address};db.Orders.Add(order);db.SaveChanges();foreach(var i in cart)db.OrderDetails.Add(new OrderDetail{OrderID=order.OrderID,ProductID=i.ProductID,Quantity=i.Quantity,UnitPrice=i.UnitPrice});db.SaveChanges();Session["Cart"]=new List<CartItem>();TempData["Message"]="Đặt hàng thành công. Mã đơn: "+order.OrderID;return RedirectToAction("History");} public ActionResult History(){if(Session["Username"]==null)return RedirectToAction("Login","Account");var c=db.Customers.FirstOrDefault(x=>x.Username==(string)Session["Username"]);if(c==null)return View(new List<StoreOrder>());return View(db.Orders.Where(o=>o.CustomerID==c.CustomerID).OrderByDescending(o=>o.OrderDate).ToList());} } }